cache_signal.example:
import { cache, cacheSignal } from 'react';

const fetchData = cache(async (id) => {
  const signal = cacheSignal();
  const result = await fetch(`/api/${id}`, { signal });
  return result.json();
});

dynamic_page_with_cache.example:
export default async function ProductPage({ params, searchParams }) {
  const { id } = await params;
  const { variant } = await searchParams;

  return (
    <>
      <StaticHeader /> {/* Cached */}
      <ProductDetails productId={id} variant={variant} /> {/* Dynamic */}
      <StaticFooter /> {/* Cached */}
    </>
  );
}

async function StaticHeader() {
  'use cache'
  return <header>...</header>;
}

form_with_instant_updates.example:
'use server'
import { updateTag } from 'next/cache';

export async function updateSettings(formData: FormData) {
  const settings = Object.fromEntries(formData);
  await db.settings.update(userId, settings);
  updateTag(`user-${userId}-settings`);
  // User sees changes instantly, no page refresh
}

tabbed_interface.example:
import { Activity } from 'react';

function Dashboard() {
  const [tab, setTab] = useState('overview');

  return (
    <>
      <TabBar activeTab={tab} onTabChange={setTab} />
      <Activity mode={tab === 'overview' ? 'visible' : 'hidden'}>
        <OverviewTab />
      </Activity>
      <Activity mode={tab === 'analytics' ? 'visible' : 'hidden'}>
        <AnalyticsTab />
      </Activity>
    </>
  );
}
